import { db } from "./src/db";
import { transactions, creditCards, fixedTransactions } from "./src/db/schema";
import { eq, and } from "drizzle-orm";

async function main() {
  const allCards = await db.select().from(creditCards);
  console.log("Cards:");
  allCards.forEach(c => console.log(`  ${c.id}: ${c.name} (Due: ${c.dueDay}, Closing: ${c.closingDay})`));

  const nubankCard = allCards.find(c => c.name.toLowerCase().includes("nubank"));
  if (!nubankCard) return console.log("Nubank card not found");

  const cardTxs = await db.select().from(transactions).where(
    and(
      eq(transactions.creditCardId, nubankCard.id),
      eq(transactions.competencyMonth, "2026-08")
    )
  );

  console.log(`\nFound ${cardTxs.length} real txs for Nubank in 2026-08:`);
  let pendingSum = 0;
  let paidSum = 0;
  cardTxs.forEach(t => {
    console.log(`  [${t.status}] ${t.date} - ${t.description} (R$ ${t.amount})`);
    if (t.status === "pending") pendingSum += Number(t.amount);
    else paidSum += Number(t.amount);
  });

  console.log(`\nTotals -> Pending: ${pendingSum}, Paid: ${paidSum}`);
}
main().catch(console.error);

import { db } from '../src/db';
import { transactions, fixedTransactions, importLogs, accounts } from '../src/db/schema';
import { sql } from 'drizzle-orm';

async function main() {
  console.log("Iniciando limpeza do banco de dados (Transações)...");
  try {
    // 1. Apagar todas as transações normais e fixas rapidamente usando TRUNCATE
    await db.execute(sql`TRUNCATE TABLE transactions CASCADE`);
    await db.execute(sql`TRUNCATE TABLE fixed_transactions CASCADE`);
    console.log("✅ Todas as transações (normais e fixas) foram apagadas.");

    // 2. Apagar logs de importação
    await db.execute(sql`TRUNCATE TABLE import_logs CASCADE`);
    console.log("✅ Logs de importação apagados.");

    // 3. Resetar saldo das contas bancárias
    await db.update(accounts).set({ currentBalance: '0' });
    console.log("✅ Saldo de todas as contas resetado para R$ 0,00.");

    console.log("\n🚀 Limpeza concluída com sucesso! Suas contas, cartões e categorias foram mantidos intactos.");
  } catch (error) {
    console.error("❌ Erro ao limpar banco de dados:", error);
  } finally {
    process.exit(0);
  }
}

main();

'use client';

import { useState } from 'react';
import { createAccount, updateAccount } from '@/app/actions/accounts';
import { Button } from '@/components/ui/button';
import { CurrencyInput } from '@/components/ui/currency-input';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Plus, Loader2 } from 'lucide-react';

type Account = {
  id: number;
  name: string;
  type: string;
  currentBalance: string;
};

export function AccountFormDialog({ 
  accountToEdit, 
  trigger,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  hideTrigger
}: { 
  accountToEdit?: Account, 
  trigger?: React.ReactNode,
  open?: boolean,
  onOpenChange?: (open: boolean) => void,
  hideTrigger?: boolean
}) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;

  const handleOpenChange = (value: boolean) => {
    if (isControlled && controlledOnOpenChange) {
      controlledOnOpenChange(value);
    } else {
      setUncontrolledOpen(value);
    }
  };

  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState('');
  const [balance, setBalance] = useState<number>(accountToEdit ? Number(accountToEdit.currentBalance) : 0);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsPending(true);
    setError('');

    const formData = new FormData(e.currentTarget);
    const name = formData.get('name') as string;
    const type = formData.get('type') as string;
    const currentBalance = formData.get('currentBalance') as string;

    const result = accountToEdit 
      ? await updateAccount(accountToEdit.id, {
          name,
          type,
          currentBalance,
        })
      : await createAccount({
          name,
          type,
          currentBalance,
        });

    setIsPending(false);

    if (result.success) {
      handleOpenChange(false);
    } else {
      setError(result.error || `Erro ao ${accountToEdit ? 'atualizar' : 'criar'} conta`);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      {!hideTrigger && (
        <DialogTrigger asChild>
          {trigger || <Button className="cursor-pointer"><Plus className="w-4 h-4 mr-2 md:mr-2 pointer-events-none" /><span className="hidden md:inline pointer-events-none">Nova Conta</span><span className="md:hidden pointer-events-none">Conta</span></Button>}
        </DialogTrigger>
      )}
      <DialogContent className="sm:max-w-[425px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>{accountToEdit ? 'Editar Conta' : 'Nova Conta'}</DialogTitle>
            <DialogDescription>
              {accountToEdit ? 'Altere as informações da sua conta bancária.' : 'Adicione uma nova conta bancária ou carteira.'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name">Nome da Conta</Label>
              <Input id="name" name="name" required placeholder="Ex: Nubank, Itaú..." defaultValue={accountToEdit?.name} />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="type">Tipo</Label>
              <Select name="type" defaultValue={accountToEdit?.type || 'checking'} required>
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Selecione o tipo..." />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="checking">Conta Corrente</SelectItem>
                  <SelectItem value="savings">Poupança</SelectItem>
                  <SelectItem value="wallet">Carteira (Dinheiro)</SelectItem>
                  <SelectItem value="stash">Caixinha</SelectItem>
                  <SelectItem value="food">Alimentação</SelectItem>
                  <SelectItem value="meal">Refeição</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="currentBalance">{accountToEdit ? 'Saldo Atual' : 'Saldo Atual Inicial'}</Label>
              <CurrencyInput id="currentBalance" name="currentBalance" required value={balance} onValueChange={setBalance} />
            </div>
            {error && <p className="text-sm text-destructive">{error}</p>}
          </div>
          <DialogFooter>
            <Button type="submit" isLoading={isPending} disabled={isPending}>

              {isPending ? 'Salvando...' : 'Salvar Conta'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useTransition } from 'react';
import { SlidersHorizontal, AlertTriangle, Info, Loader2 } from 'lucide-react';
import { adjustAccountBalance } from '@/app/actions/accounts';
import { Button } from '@/components/ui/button';
import { CurrencyInput } from '@/components/ui/currency-input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';

type Account = {
  id: number;
  name: string;
  currentBalance: string;
};

interface AdjustBalanceDialogProps {
  account: Account;
  trigger?: React.ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  hideTrigger?: boolean;
}

export function AdjustBalanceDialog({
  account,
  trigger,
  open: controlledOpen,
  onOpenChange: controlledOnOpenChange,
  hideTrigger
}: AdjustBalanceDialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const isControlled = controlledOpen !== undefined;
  const open = isControlled ? controlledOpen : uncontrolledOpen;

  const [realBalance, setRealBalance] = useState<number>(Number(account.currentBalance));
  const [adjustmentMode, setAdjustmentMode] = useState<'transaction' | 'initial_balance'>('transaction');
  const [error, setError] = useState('');
  const [isPending, startTransition] = useTransition();

  // Reset state when dialog opens
  const handleOpenChange = (value: boolean) => {
    if (isControlled && controlledOnOpenChange) {
      controlledOnOpenChange(value);
    } else {
      setUncontrolledOpen(value);
    }

    if (value) {
      setRealBalance(Number(account.currentBalance));
      setError('');
    }
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');

    startTransition(async () => {
      const createTransaction = adjustmentMode === 'transaction';
      const result = await adjustAccountBalance(account.id, realBalance, createTransaction);
      if (result.success) {
        handleOpenChange(false);
      } else {
        setError(result.error ?? 'Erro ao ajustar saldo.');
      }
    });
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      {!hideTrigger && (
        <DialogTrigger asChild>
          {trigger ?? (
            <Button variant="outline" size="sm">
              <SlidersHorizontal className="h-4 w-4 mr-2" />
              Reajustar Saldo
            </Button>
          )}
        </DialogTrigger>
      )}

      <DialogContent className="sm:max-w-[420px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <SlidersHorizontal className="h-5 w-5 text-primary" />
              Reajustar Saldo
            </DialogTitle>
            <DialogDescription>
              {account.name}
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-5 py-5">
            <div className="grid gap-2">
              <Label htmlFor="realBalance">Saldo Real no Banco</Label>
              <CurrencyInput
                id="realBalance"
                name="realBalance"
                value={realBalance}
                onValueChange={setRealBalance}
                required
              />
            </div>

            <div className="grid gap-3">
              <Label className="text-muted-foreground ml-1">Opção de Ajuste</Label>
              <div className="flex flex-col gap-3 p-4 rounded-xl bg-muted/20 border border-border/50">
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    type="radio"
                    checked={adjustmentMode === "transaction"}
                    onChange={() => setAdjustmentMode("transaction")}
                    className="accent-primary h-4 w-4"
                  />
                  Criar transação de ajuste
                </label>
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    type="radio"
                    checked={adjustmentMode === "initial_balance"}
                    onChange={() => setAdjustmentMode("initial_balance")}
                    className="accent-primary h-4 w-4"
                  />
                  Apenas corrigir valor inicial
                </label>
              </div>
            </div>

            {adjustmentMode === "transaction" ? (
              <div className="flex items-start gap-3 rounded-lg border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-600 dark:text-amber-400">
                <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                <p>
                  Isso criará uma transação de ajuste automático no seu histórico para sincronizar seu saldo.
                </p>
              </div>
            ) : (
              <div className="flex items-start gap-3 rounded-lg border border-blue-500/30 bg-blue-500/10 px-4 py-3 text-sm text-blue-600 dark:text-blue-400">
                <Info className="mt-0.5 h-4 w-4 shrink-0" />
                <p>
                  O saldo será corrigido diretamente, sem criar nenhuma transação no histórico.
                </p>
              </div>
            )}

            {error && (
              <p className="text-sm text-destructive">{error}</p>
            )}
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="ghost"
              onClick={() => handleOpenChange(false)}
              disabled={isPending}
            >
              Cancelar
            </Button>
            <Button type="submit" isLoading={isPending} disabled={isPending}>

              {isPending ? 'Ajustando...' : 'Confirmar Ajuste'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { Switch } from '@/components/ui/switch';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Trash2, Loader2, Plus } from 'lucide-react';
import { CATEGORY_ICONS_LIST, CategoryIcon } from '@/components/category-icon';
import {
  toggleCategoryPrediction,
  toggleSubcategoryPrediction,
  deleteCategory,
  deleteSubcategory,
  updateCategoryName,
  updateSubcategoryName,
  updateCategoryIcon,
  createSubcategory,
} from '@/app/actions/categories';

export type Subcategory = {
  id: number;
  name: string;
  isPredictable: boolean;
};

export type Category = {
  id: number;
  name: string;
  icon: string;
  type: string;
  isPredictable: boolean;
  subcategories: Subcategory[];
};

export function CategoryTree({ categories }: { categories: Category[] }) {
  return (
    <Accordion type="multiple" className="w-full space-y-4">
      {categories.map((category) => (
        <CategoryAccordionItem key={category.id} category={category} />
      ))}
    </Accordion>
  );
}

function CategoryAccordionItem({ category }: { category: Category }) {
  const [isEditingName, setIsEditingName] = useState(false);
  const [name, setName] = useState(category.name);
  const [isPending, setIsPending] = useState(false);
  const [isPopoverOpen, setIsPopoverOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditingName && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isEditingName]);

  const handleSaveName = async () => {
    setIsEditingName(false);
    if (name !== category.name && name.trim() !== '') {
      setIsPending(true);
      const res = await updateCategoryName(category.id, name.trim());
      setIsPending(false);
      if (!res.success) {
        setName(category.name);
        alert(res.error || 'Erro ao atualizar nome');
      }
    } else {
      setName(category.name);
    }
  };

  const handleUpdateIcon = async (iconName: string) => {
    setIsPopoverOpen(false);
    setIsPending(true);
    const res = await updateCategoryIcon(category.id, iconName);
    setIsPending(false);
    if (!res.success) alert(res.error || 'Erro ao atualizar ícone');
  };

  const handleTogglePrediction = async (checked: boolean) => {
    setIsPending(true);
    const res = await toggleCategoryPrediction(category.id, checked);
    setIsPending(false);
    if (!res.success) alert(res.error || 'Erro ao atualizar previsão');
  };

  const handleDelete = async () => {
    if (!confirm(`Tem certeza que deseja excluir a categoria ${category.name}?`)) return;
    setIsPending(true);
    const res = await deleteCategory(category.id);
    setIsPending(false);
    if (!res.success) alert(res.error || 'Erro ao excluir categoria');
  };

  return (
    <AccordionItem value={category.id.toString()} className="border rounded-lg bg-card text-card-foreground shadow-sm px-4">
      <div className="flex items-center justify-between py-2">
        <div className="flex flex-1 items-center gap-3">
          {/* Ícone via Popover */}
          <Popover open={isPopoverOpen} onOpenChange={setIsPopoverOpen}>
            <PopoverTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                className={`h-8 w-8 shrink-0 ${category.type === 'expense' ? 'text-red-500 hover:text-red-600 hover:bg-red-50' : 'text-green-500 hover:text-green-600 hover:bg-green-50'}`}
                isLoading={isPending} disabled={isPending}
                onClick={(e) => e.stopPropagation()}
              >
                <CategoryIcon name={category.icon} className="h-5 w-5" />
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-64 p-2" align="start" side="bottom">
              <div className="grid grid-cols-5 gap-2 max-h-48 overflow-y-auto">
                {CATEGORY_ICONS_LIST.map(({ name: iconName, Icon }) => (
                  <button
                    key={iconName}
                    onClick={() => handleUpdateIcon(iconName)}
                    className="flex items-center justify-center p-2 rounded-md hover:bg-muted transition-colors"
                  >
                    <Icon className="h-5 w-5 text-muted-foreground" />
                  </button>
                ))}
              </div>
            </PopoverContent>
          </Popover>

          {/* Nome Inline Edit */}
          {isEditingName ? (
            <Input
              ref={inputRef}
              value={name}
              onChange={(e) => setName(e.target.value)}
              onBlur={handleSaveName}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSaveName();
                if (e.key === 'Escape') {
                  setName(category.name);
                  setIsEditingName(false);
                }
              }}
              className="h-8 w-full max-w-[200px]"
              disabled={isPending}
            />
          ) : (
            <span
              className="text-lg font-semibold cursor-text hover:bg-muted/50 px-2 py-0.5 rounded transition-colors"
              onClick={(e) => {
                e.stopPropagation();
                setIsEditingName(true);
              }}
            >
              {name}
            </span>
          )}
        </div>

        <div className="flex items-center gap-4 shrink-0">
          <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
            <span className="text-sm text-muted-foreground">Previsão</span>
            <Switch
              checked={category.isPredictable}
              onCheckedChange={handleTogglePrediction}
              disabled={isPending}
            />
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
            onClick={(e) => {
              e.stopPropagation();
              handleDelete();
            }}
            disabled={isPending}
          >
            <Trash2 className="h-4 w-4" />
          </Button>

          <AccordionTrigger className="w-8 justify-center py-0" />
        </div>
      </div>

      <AccordionContent className="pt-2 pb-4">
        <div className="pl-12 space-y-2">
          {category.subcategories && category.subcategories.length > 0 ? (
            <ul className="space-y-1">
              {category.subcategories.map((sub) => (
                <SubcategoryItem key={sub.id} subcategory={sub} />
              ))}
            </ul>
          ) : (
            <p className="text-sm text-muted-foreground italic mb-2">Sem subcategorias cadastradas.</p>
          )}
          <QuickAddSubcategory categoryId={category.id} />
        </div>
      </AccordionContent>
    </AccordionItem>
  );
}

function SubcategoryItem({ subcategory }: { subcategory: Subcategory }) {
  const [isEditingName, setIsEditingName] = useState(false);
  const [name, setName] = useState(subcategory.name);
  const [isPending, setIsPending] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isEditingName && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isEditingName]);

  const handleSaveName = async () => {
    setIsEditingName(false);
    if (name !== subcategory.name && name.trim() !== '') {
      setIsPending(true);
      const res = await updateSubcategoryName(subcategory.id, name.trim());
      setIsPending(false);
      if (!res.success) {
        setName(subcategory.name);
        alert(res.error || 'Erro ao atualizar nome');
      }
    } else {
      setName(subcategory.name);
    }
  };

  const handleTogglePrediction = async (checked: boolean) => {
    setIsPending(true);
    const res = await toggleSubcategoryPrediction(subcategory.id, checked);
    setIsPending(false);
    if (!res.success) alert(res.error || 'Erro ao atualizar previsão');
  };

  const handleDelete = async () => {
    if (!confirm(`Tem certeza que deseja excluir a subcategoria ${subcategory.name}?`)) return;
    setIsPending(true);
    const res = await deleteSubcategory(subcategory.id);
    setIsPending(false);
    if (!res.success) alert(res.error || 'Erro ao excluir subcategoria');
  };

  return (
    <li className="flex items-center justify-between p-2 rounded-md hover:bg-muted/30 transition-colors group">
      <div className="flex items-center gap-2 flex-1">
        <div className="w-1.5 h-1.5 rounded-full bg-muted-foreground shrink-0" />
        {isEditingName ? (
          <Input
            ref={inputRef}
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={handleSaveName}
            onKeyDown={(e) => {
              if (e.key === 'Enter') handleSaveName();
              if (e.key === 'Escape') {
                setName(subcategory.name);
                setIsEditingName(false);
              }
            }}
            className="h-7 text-sm w-full max-w-[200px]"
            disabled={isPending}
          />
        ) : (
          <span
            className="text-sm cursor-text hover:bg-muted px-1.5 py-0.5 rounded transition-colors"
            onClick={() => setIsEditingName(true)}
          >
            {name}
          </span>
        )}
      </div>

      <div className="flex items-center gap-3">
        <Switch
          checked={subcategory.isPredictable}
          onCheckedChange={handleTogglePrediction}
          disabled={isPending}
        />
        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6 text-destructive/70 hover:text-destructive hover:bg-destructive/10"
          onClick={handleDelete}
          isLoading={isPending} disabled={isPending}
        >
          <Trash2 className="h-3 w-3" />
        </Button>
      </div>
    </li>
  );
}

function QuickAddSubcategory({ categoryId }: { categoryId: number }) {
  const [name, setName] = useState('');
  const [isPending, setIsPending] = useState(false);

  const handleAdd = async () => {
    if (!name.trim()) return;
    setIsPending(true);
    const res = await createSubcategory(name.trim(), categoryId.toString());
    setIsPending(false);
    if (res.success) {
      setName('');
    } else {
      alert(res.error || 'Erro ao adicionar subcategoria');
    }
  };

  return (
    <div className="flex items-center gap-2 mt-2 w-full max-w-sm">
      <Input
        value={name}
        onChange={(e) => setName(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            handleAdd();
          }
        }}
        placeholder="Nova subcategoria... + Enter"
        className="h-8 text-sm"
        disabled={isPending}
      />
      <Button 
        size="sm" 
        variant="secondary" 
        className="h-8 shrink-0" 
        onClick={handleAdd}
        isLoading={isPending} disabled={isPending || !name.trim()}
      >
        <Plus className="h-4 w-4" />
      </Button>
    </div>
  );
}

'use client';

import { useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { CurrencyInput } from '@/components/ui/currency-input';
import { adjustInvoice } from '@/app/actions/credit-cards';
import { Loader2, Settings2, TrendingUp, TrendingDown, Check } from 'lucide-react';

interface AdjustInvoiceDialogProps {
  creditCardId: number;
  competencyMonth: string;
  totalAmount: number;
}

export function AdjustInvoiceDialog({ creditCardId, competencyMonth, totalAmount }: AdjustInvoiceDialogProps) {
  const [open, setOpen] = useState(false);
  const [realAmount, setRealAmount] = useState<number>(0);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const difference = realAmount - totalAmount;
  const absDifference = Math.abs(difference);
  const hasNoDifference = Math.abs(difference) < 0.01;
  const isIncrease = difference > 0;

  const handleRealAmountChange = useCallback((value: number) => {
    setRealAmount(value);
  }, []);

  const handleSubmit = async () => {
    if (realAmount <= 0) {
      alert('Informe um valor válido maior que zero.');
      return;
    }

    if (hasNoDifference) {
      setOpen(false);
      return;
    }

    setIsSubmitting(true);
    const result = await adjustInvoice(creditCardId, competencyMonth, realAmount);
    setIsSubmitting(false);

    if (result.success) {
      setOpen(false);
      setRealAmount(0);
    } else {
      alert(result.error || 'Erro ao ajustar fatura');
    }
  };

  const handleOpenChange = (newOpen: boolean) => {
    setOpen(newOpen);
    if (!newOpen) {
      setRealAmount(0);
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        <Button variant="outline" className="w-full sm:w-auto gap-2">
          <Settings2 className="w-4 h-4" />
          Ajustar Fatura
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Ajustar Valor da Fatura</DialogTitle>
          <DialogDescription>
            Informe o valor real da fatura (conforme o app do seu banco/cartão). Se houver diferença, uma transação de ajuste será criada automaticamente.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="flex items-center justify-between p-3 rounded-lg bg-muted/50">
            <span className="text-sm text-muted-foreground">Valor calculado atual:</span>
            <span className="font-semibold">{formatCurrency(totalAmount)}</span>
          </div>

          <div className="space-y-2">
            <Label htmlFor="real-amount">Valor Real da Fatura (R$)</Label>
            <CurrencyInput
              id="real-amount"
              name="realAmount"
              onValueChange={handleRealAmountChange}
              required
            />
          </div>

          {realAmount > 0 && (
            <div className={`flex items-center justify-between p-3 rounded-lg border ${
              hasNoDifference
                ? 'bg-green-500/10 border-green-500/30'
                : isIncrease
                  ? 'bg-red-500/10 border-red-500/30'
                  : 'bg-blue-500/10 border-blue-500/30'
            }`}>
              <div className="flex items-center gap-2">
                {hasNoDifference ? (
                  <Check className="w-4 h-4 text-green-500" />
                ) : isIncrease ? (
                  <TrendingUp className="w-4 h-4 text-red-500" />
                ) : (
                  <TrendingDown className="w-4 h-4 text-blue-500" />
                )}
                <span className="text-sm font-medium">
                  {hasNoDifference
                    ? 'Valores iguais — sem ajuste necessário'
                    : isIncrease
                      ? 'Será criado um ajuste de fatura'
                      : 'Será criado um adiantamento de fatura'}
                </span>
              </div>
              {!hasNoDifference && (
                <span className={`font-bold ${isIncrease ? 'text-red-500' : 'text-blue-500'}`}>
                  {isIncrease ? '+' : '-'}{formatCurrency(absDifference)}
                </span>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button type="button" variant="outline" onClick={() => setOpen(false)} disabled={isSubmitting}>
            Cancelar
          </Button>
          <Button
            onClick={handleSubmit}
            isLoading={isSubmitting} disabled={realAmount <= 0 || hasNoDifference || isSubmitting}
          >

            Confirmar Ajuste
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

