"use client";

import { useState } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Upload, FileText, CheckCircle2, AlertCircle } from "lucide-react";
import { importCSV } from "@/app/actions/import";

type ImportResult = {
  success: boolean;
  error?: string;
  result?: {
    totalRows: number;
    successRows: number;
    skippedRows: number;
    errorRows: number;
    errorsDetail: { row: number; data: Record<string, string>; error: string }[];
  };
};

export default function ImportPage() {
  const [activeTab, setActiveTab] = useState<"expense" | "income" | "transfer">("expense");
  const [file, setFile] = useState<File | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [importResult, setImportResult] = useState<ImportResult | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
      setImportResult(null); // Reseta o resultado ao selecionar novo arquivo
    }
  };

  const handleImport = async () => {
    if (!file) return;

    setIsImporting(true);
    setImportResult(null);

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const csvString = event.target?.result as string;
        if (csvString) {
          const res = await importCSV(csvString, activeTab, file.name);
          setImportResult(res);
        }
        setIsImporting(false);
      };
      reader.onerror = () => {
        setImportResult({ success: false, error: "Falha ao ler o arquivo." });
        setIsImporting(false);
      };
      reader.readAsText(file);
    } catch (error) {
      const e = error as Error;
      setImportResult({ success: false, error: e.message || "Erro desconhecido." });
      setIsImporting(false);
    }
  };

  return (
    <div className="container mx-auto p-4 max-w-3xl space-y-6 pb-24">
      <div>
        <h1 className="text-3xl font-bold tracking-tight mb-2">Importar Transações</h1>
        <p className="text-muted-foreground">
          Faça o upload do seu arquivo CSV contendo os registros de despesas, receitas ou transferências.
        </p>
      </div>

      <Tabs 
        value={activeTab} 
        onValueChange={(val) => {
          setActiveTab(val as "expense" | "income" | "transfer");
          setFile(null);
          setImportResult(null);
        }}
        className="w-full"
      >
        <TabsList className="grid w-full grid-cols-3 mb-6">
          <TabsTrigger value="expense">Despesas</TabsTrigger>
          <TabsTrigger value="income">Receitas</TabsTrigger>
          <TabsTrigger value="transfer">Transferências</TabsTrigger>
        </TabsList>

        <Card className="border-border">
          <CardHeader>
            <CardTitle>Upload de CSV - {activeTab === 'expense' ? 'Despesas' : activeTab === 'income' ? 'Receitas' : 'Transferências'}</CardTitle>
            <CardDescription>
              Selecione o arquivo CSV contendo suas {activeTab === 'expense' ? 'despesas' : activeTab === 'income' ? 'receitas' : 'transferências'} para importação.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="w-full">
              <Label 
                htmlFor="csv-file"
                className="flex flex-col items-center justify-center w-full h-40 border-2 border-dashed border-muted-foreground/25 rounded-xl cursor-pointer bg-muted/20 hover:bg-muted/50 transition-colors"
              >
                <div className="flex flex-col items-center justify-center pt-5 pb-6">
                  <Upload className="w-10 h-10 mb-3 text-muted-foreground/60" />
                  <p className="mb-2 text-sm text-muted-foreground">
                    <span className="font-semibold text-foreground">Clique para selecionar</span> ou arraste e solte
                  </p>
                  <p className="text-xs text-muted-foreground">
                    Apenas arquivos .CSV são suportados
                  </p>
                </div>
                <Input 
                  id="csv-file" 
                  type="file" 
                  accept=".csv" 
                  className="hidden"
                  onChange={handleFileChange}
                />
              </Label>
            </div>

            {file && (
              <div className="flex items-center gap-3 text-sm bg-background border rounded-lg p-3">
                <div className="p-2 bg-primary/10 rounded-md">
                  <FileText className="w-5 h-5 text-primary" />
                </div>
                <div className="flex flex-col flex-1 overflow-hidden">
                  <span className="font-medium truncate">{file.name}</span>
                  <span className="text-xs text-muted-foreground">{(file.size / 1024).toFixed(1)} KB</span>
                </div>
              </div>
            )}

            <Button 
              className="w-full h-11" 
              onClick={handleImport} 
              disabled={!file || isImporting}
            >
              {isImporting ? (
                "Processando Importação..."
              ) : (
                <>
                  <Upload className="w-4 h-4 mr-2" />
                  Iniciar Importação de {activeTab === 'expense' ? 'Despesas' : activeTab === 'income' ? 'Receitas' : 'Transferências'}
                </>
              )}
            </Button>
          </CardContent>
        </Card>
      </Tabs>

      {importResult && (
        <Card className={`overflow-hidden border-2 ${importResult.success ? 'border-green-500/30' : 'border-destructive/30'}`}>
          <div className={`h-1.5 w-full ${importResult.success ? 'bg-green-500' : 'bg-destructive'}`} />
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              {importResult.success ? (
                <>
                  <CheckCircle2 className="w-5 h-5 text-green-500" />
                  Importação Concluída
                </>
              ) : (
                <>
                  <AlertCircle className="w-5 h-5 text-destructive" />
                  Erro na Importação
                </>
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {importResult.success && importResult.result ? (
              <div className="space-y-6">
                <div className="grid grid-cols-4 gap-4 text-center">
                  <div className="bg-muted/50 rounded-xl p-4 border border-border">
                    <div className="text-3xl font-bold">{importResult.result.totalRows}</div>
                    <div className="text-xs text-muted-foreground mt-1">Total de Linhas</div>
                  </div>
                  <div className="bg-green-500/10 rounded-xl p-4 border border-green-500/20">
                    <div className="text-3xl font-bold text-green-600 dark:text-green-400">
                      {importResult.result.successRows}
                    </div>
                    <div className="text-xs text-green-600/80 dark:text-green-400/80 mt-1">Sucesso</div>
                  </div>
                  <div className="bg-yellow-500/10 rounded-xl p-4 border border-yellow-500/20">
                    <div className="text-3xl font-bold text-yellow-600 dark:text-yellow-400">
                      {importResult.result.skippedRows}
                    </div>
                    <div className="text-xs text-yellow-600/80 dark:text-yellow-400/80 mt-1">Ignoradas (já existiam)</div>
                  </div>
                  <div className="bg-destructive/10 rounded-xl p-4 border border-destructive/20">
                    <div className="text-3xl font-bold text-destructive">
                      {importResult.result.errorRows}
                    </div>
                    <div className="text-xs text-destructive/80 mt-1">Erros</div>
                  </div>
                </div>

                {importResult.result.errorsDetail && importResult.result.errorsDetail.length > 0 && (
                  <div className="mt-6">
                    <h4 className="font-semibold text-sm mb-3 flex items-center gap-2">
                      <AlertCircle className="w-4 h-4 text-destructive" />
                      Detalhes dos Erros
                    </h4>
                    <div className="max-h-[300px] overflow-y-auto space-y-2 rounded-lg border border-border p-1 bg-muted/30">
                      {importResult.result.errorsDetail.map((err, i) => (
                        <div key={i} className="text-sm p-3 bg-background rounded-md border border-border flex flex-col gap-1">
                          <span className="font-medium text-destructive">Linha {err.row}</span>
                          <span className="text-muted-foreground">{err.error}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-destructive font-medium p-4 bg-destructive/10 rounded-lg">
                {importResult.error || "Ocorreu um erro desconhecido durante a importação."}
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { getAllocationSettings } from '@/app/actions/allocations';
import { AllocationConfigDialog } from '@/components/allocation-config-dialog';
import { Wallet } from 'lucide-react';
import { format, parse } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface BalanceAllocatorProps {
  projectedBalance: number;
  competencyMonth?: string;
}

export async function BalanceAllocator({ projectedBalance, competencyMonth }: BalanceAllocatorProps) {
  const { baseKeepAmount, rules } = await getAllocationSettings();

  const distributableAmount = projectedBalance - baseKeepAmount;

  const safeMonth = competencyMonth || format(new Date(), "yyyy-MM");
  const dateObj = parse(safeMonth, "yyyy-MM", new Date());
  const monthName = format(dateObj, "MMMM", { locale: ptBR });
  const capitalizedMonth = monthName.charAt(0).toUpperCase() + monthName.slice(1);

  return (
    <Card className="mt-6 border-primary/20 shadow-sm">
      <CardHeader className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4">
        <div className="space-y-1.5">
          <CardTitle className="text-xl font-bold flex items-center gap-2">
            <Wallet className="w-5 h-5 text-primary" />
            Distribuição Sugerida para o Fim de {capitalizedMonth}
          </CardTitle>
          <CardDescription className="text-sm flex flex-wrap items-center gap-x-2 gap-y-1">
            <span>Saldo Projetado: <strong className="text-foreground">{formatBRL(projectedBalance)}</strong></span>
            <span className="hidden sm:inline text-border">|</span>
            <span>Retido na Conta: <strong className="text-foreground">{formatBRL(baseKeepAmount)}</strong></span>
            <span className="hidden sm:inline text-border">|</span>
            <span>Disponível para distribuir: <strong className="text-primary">{formatBRL(Math.max(0, distributableAmount))}</strong></span>
          </CardDescription>
        </div>
        <div className="shrink-0 self-start sm:self-auto">
          <AllocationConfigDialog initialData={{ baseKeepAmount, rules }} />
        </div>
      </CardHeader>

      <CardContent>
        {distributableAmount <= 0 ? (
          <div className="bg-muted/30 border border-dashed rounded-lg p-6 text-center text-muted-foreground text-sm">
            Não há saldo projetado suficiente para distribuição após reter o valor base de {formatBRL(baseKeepAmount)}.
          </div>
        ) : rules.length === 0 ? (
          <div className="bg-muted/30 border border-dashed rounded-lg p-6 text-center text-muted-foreground text-sm">
            Nenhuma regra configurada. O valor excedente permanecerá na conta.
          </div>
        ) : (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mt-4">
            {rules.map((rule) => {
              const ruleAmount = distributableAmount * (rule.percentage / 100);
              return (
                <div key={rule.id} className="bg-card border border-white/5 rounded-2xl p-5 hover:border-primary/30 transition-colors">
                  {/* Linha Superior do Card */}
                  <div className="flex items-center justify-between">
                    <span className="font-medium text-sm sm:text-base truncate pr-2 text-foreground" title={rule.name}>
                      {rule.name}
                    </span>
                    <div className="w-10 h-10 shrink-0 rounded-full flex items-center justify-center border-2 border-primary/30 text-xs font-bold text-primary bg-primary/5">
                      {rule.percentage}%
                    </div>
                  </div>

                  {/* Linha Inferior do Card */}
                  <div className="text-xl sm:text-2xl font-bold mt-4 text-primary truncate" title={formatBRL(ruleAmount)}>
                    {formatBRL(ruleAmount)}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function formatBRL(value: number) {
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

'use client';

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { CalendarDays, ArrowDownCircle, ArrowUpCircle, TrendingUp, TrendingDown } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';

type ForecastTransaction = {
  id: number | string;
  type: string;
  description: string;
  amount: string | number;
  account?: { name: string } | null;
  creditCard?: { name: string } | null;
  category?: { name: string } | null;
  parentTransactionId?: number | null;
};

type DayProjection = {
  date: string;
  total_expenses: number;
  total_incomes: number;
  projected_balance: number;
  transactions_of_the_day: ForecastTransaction[];
};

export function DayByDayForecast({ projection }: { projection: DayProjection[] }) {
  const [selectedDay, setSelectedDay] = useState<DayProjection | null>(null);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatDay = (dateStr: string) => {
    return format(parseISO(dateStr), "dd/MM", { locale: ptBR });
  };

  const formatDayFull = (dateStr: string) => {
    return format(parseISO(dateStr), "dd 'de' MMMM, EEEE", { locale: ptBR });
  };

  return (
    <>
      <Card className="flex flex-col h-[600px]">
        <CardHeader>
          <CardTitle className="text-lg font-medium flex items-center gap-2">
            <CalendarDays className="w-5 h-5 text-muted-foreground" />
            Previsão Dia a Dia
          </CardTitle>
        </CardHeader>
        <CardContent className="flex-1 overflow-y-auto pr-2 space-y-3">
          {projection.filter(day => day.total_expenses > 0 || day.total_incomes > 0).length === 0 ? (
            <div className="text-center py-12 text-muted-foreground text-sm border rounded-xl border-dashed">
              Nenhuma movimentação prevista.
            </div>
          ) : (
            projection.filter(day => day.total_expenses > 0 || day.total_incomes > 0).map((day) => {
              const hasExpenses = day.total_expenses > 0;
              const hasIncomes = day.total_incomes > 0;
              const isNegativeBalance = day.projected_balance < 0;

              return (
                <div
                  key={day.date}
                  onClick={() => setSelectedDay(day)}
                  className="group p-2 md:p-3 border rounded-xl bg-card hover:bg-muted/40 transition-all flex items-center gap-2 md:gap-4 text-sm cursor-pointer hover:border-primary/40 hover:shadow-sm"
                >
                  {/* Esquerda: Data Destaque */}
                  <div className="flex flex-col items-center justify-center bg-muted/50 rounded-lg p-1.5 md:p-2 w-12 h-12 md:w-16 md:h-16 flex-shrink-0 group-hover:bg-primary/10 transition-colors">
                    <span className="text-lg md:text-xl font-bold text-foreground">{format(parseISO(day.date), "dd")}</span>
                    <span className="text-[10px] md:text-xs text-muted-foreground uppercase">{format(parseISO(day.date), "MMM", { locale: ptBR })}</span>
                  </div>

                  {/* Centro: Movimentações */}
                  <div className="flex flex-1 flex-col justify-center gap-1 min-w-0">
                    <div className="flex items-center gap-1 md:gap-1.5 truncate">
                      <TrendingDown className={`w-3 h-3 md:w-4 md:h-4 shrink-0 ${hasExpenses ? 'text-red-500' : 'text-muted-foreground/40'}`} />
                      <span className={`font-medium text-xs md:text-sm truncate ${hasExpenses ? 'text-red-500' : 'text-muted-foreground'}`}>
                        {formatCurrency(day.total_expenses)}
                      </span>
                    </div>
                    <div className="flex items-center gap-1 md:gap-1.5 truncate">
                      <TrendingUp className={`w-3 h-3 md:w-4 md:h-4 shrink-0 ${hasIncomes ? 'text-green-600' : 'text-muted-foreground/40'}`} />
                      <span className={`font-medium text-xs md:text-sm truncate ${hasIncomes ? 'text-green-600' : 'text-muted-foreground'}`}>
                        {formatCurrency(day.total_incomes)}
                      </span>
                    </div>
                  </div>

                  {/* Direita: Saldo */}
                  <div className="flex flex-col items-end justify-center shrink-0">
                    <span className="text-[9px] md:text-[10px] uppercase font-semibold tracking-wider text-muted-foreground mb-0.5 md:mb-1">Saldo Previsto</span>
                    <span className={`text-sm md:text-lg font-bold truncate max-w-[90px] sm:max-w-none ${isNegativeBalance ? "text-red-500" : "text-primary"}`}>
                      {formatCurrency(day.projected_balance)}
                    </span>
                  </div>
                </div>
              );
            }))}
        </CardContent>
      </Card>

      {/* Day Detail Modal */}
      <Dialog open={!!selectedDay} onOpenChange={(open) => !open && setSelectedDay(null)}>
        <DialogContent className="sm:max-w-[550px]">
          {selectedDay && (
            <>
              <DialogHeader>
                <DialogTitle className="flex items-center gap-2">
                  <CalendarDays className="w-5 h-5 text-primary" />
                  {formatDayFull(selectedDay.date)}
                </DialogTitle>
                <DialogDescription className="sr-only">
                  Resumo financeiro do dia selecionado.
                </DialogDescription>
              </DialogHeader>

              {/* Summary Cards */}
              <div className="grid grid-cols-3 gap-3 mt-2">
                <div className="rounded-lg border p-3 text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <ArrowDownCircle className="w-4 h-4 text-red-500" />
                    <span className="text-xs text-muted-foreground">Despesas</span>
                  </div>
                  <span className="font-bold text-red-500 text-sm">
                    {formatCurrency(selectedDay.total_expenses)}
                  </span>
                </div>
                <div className="rounded-lg border p-3 text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <ArrowUpCircle className="w-4 h-4 text-green-600" />
                    <span className="text-xs text-muted-foreground">Receitas</span>
                  </div>
                  <span className="font-bold text-green-600 text-sm">
                    {formatCurrency(selectedDay.total_incomes)}
                  </span>
                </div>
                <div className="rounded-lg border p-3 text-center">
                  <div className="flex items-center justify-center gap-1 mb-1">
                    <TrendingUp className="w-4 h-4 text-primary" />
                    <span className="text-xs text-muted-foreground">Saldo</span>
                  </div>
                  <span className={`font-bold text-sm ${selectedDay.projected_balance >= 0 ? 'text-primary' : 'text-red-500'}`}>
                    {formatCurrency(selectedDay.projected_balance)}
                  </span>
                </div>
              </div>

              {/* Transactions List */}
              <div className="mt-4 max-h-[350px] overflow-y-auto">
                {selectedDay.transactions_of_the_day.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground text-sm border rounded-lg border-dashed">
                    Nenhuma movimentação neste dia.
                  </div>
                ) : (
                  <Table className="table-fixed w-full">
                    <TableHeader>
                      <TableRow>
                        <TableHead className="w-[50%] px-2">Descrição</TableHead>
                        <TableHead className="w-[20%] px-1">
                          <span className="md:hidden">Cat.</span>
                          <span className="hidden md:inline">Categoria</span>
                        </TableHead>
                        <TableHead className="w-[30%] text-right px-2">Valor</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {selectedDay.transactions_of_the_day.map((tx) => {
                        const isIncome = tx.type === 'income' || (tx.type === 'transfer' && !!tx.parentTransactionId);
                        const isTransfer = tx.type === 'transfer';
                        return (
                          <TableRow key={tx.id}>
                            <TableCell className="overflow-hidden px-2 py-3">
                              <div className="flex flex-col min-w-0">
                                <span className="font-medium text-xs md:text-sm truncate block">
                                  {isTransfer && <span className="inline-block bg-blue-100 text-blue-700 border border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800 text-[9px] uppercase px-1 rounded mr-1">Transf</span>}
                                  {tx.description}
                                </span>
                                <span className="text-[10px] md:text-xs text-muted-foreground truncate block">
                                  {tx.account?.name || tx.creditCard?.name || 'Geral'}
                                </span>
                              </div>
                            </TableCell>
                            <TableCell className="text-[10px] md:text-xs text-muted-foreground truncate px-1 py-3">
                              {tx.category?.name || '-'}
                            </TableCell>
                            <TableCell className={`text-right font-bold truncate px-2 py-3 text-xs md:text-sm ${isIncome ? 'text-green-600' : 'text-red-500'}`}>
                              {isIncome ? '+' : '-'}{formatCurrency(Number(tx.amount))}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                )}
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}

'use client';

import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { Area, AreaChart, CartesianGrid, XAxis, YAxis, ResponsiveContainer } from "recharts";
import {
  ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart";

interface PlanningChartProps {
  data: {
    date: string;
    projected_balance: number;
  }[];
}

const chartConfig = {
  projected_balance: {
    label: "Saldo Previsto",
    color: "var(--primary)",
  },
} satisfies ChartConfig;

export function PlanningChart({ data }: PlanningChartProps) {
  const formattedData = data.map((item) => ({
    ...item,
    formattedDate: format(parseISO(item.date), "dd/MM", { locale: ptBR }),
  }));

  const minBalance = Math.min(...data.map((d) => d.projected_balance));
  const maxBalance = Math.max(...data.map((d) => d.projected_balance));

  // Add some padding to Y axis, ensure it doesn't collapse if everything is 0
  const yDomain = [
    minBalance < 0 ? Math.floor(minBalance * 1.1) : 0,
    maxBalance === 0 && minBalance === 0 ? 100 : Math.ceil(maxBalance * 1.1),
  ];

  return (
    <ChartContainer config={chartConfig} className="min-h-[250px] w-full mt-4">
      <AreaChart accessibilityLayer data={formattedData} margin={{ top: 10, left: -10, right: 10, bottom: 0 }}>
        <defs>
          <linearGradient id="colorBalancePlanning" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--primary)" stopOpacity={0.5} />
            <stop offset="100%" stopColor="var(--primary)" stopOpacity={0} />
          </linearGradient>
        </defs>
        <CartesianGrid vertical={false} stroke="rgba(255,255,255,0.05)" />
        <XAxis
          dataKey="formattedDate"
          tickLine={false}
          axisLine={false}
          tickMargin={8}
          minTickGap={30}
          className="text-xs"
        />
        <YAxis 
          tickLine={false} 
          axisLine={false} 
          tickMargin={4}
          domain={yDomain}
          tickFormatter={(value) => {
            if (value === 0) return "R$ 0";
            return `R$ ${Intl.NumberFormat('pt-BR', { notation: 'compact', maximumFractionDigits: 1 }).format(value)}`;
          }}
          className="text-xs"
          width={55}
        />
        <ChartTooltip
          cursor={{ stroke: 'hsl(var(--muted-foreground))', strokeWidth: 1, strokeDasharray: '4 4' }}
          content={<ChartTooltipContent indicator="line" />}
        />
        <Area
          type="monotone"
          dataKey="projected_balance"
          stroke="var(--color-projected_balance)"
          strokeWidth={3}
          fill="url(#colorBalancePlanning)"
          dot={false}
          activeDot={{ r: 6, fill: "var(--color-projected_balance)" }}
        />
      </AreaChart>
    </ChartContainer>
  );
}

'use client';

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { WalletCards, CalendarDays, AlertTriangle } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface Transaction {
  id: number;
  type: string;
  amount: string;
  description: string;
  date: string;
  account: { id: number; name: string } | null;
  creditCard?: { id: number; name: string } | null;
  category: { id: number; name: string } | null;
  parentTransactionId?: number | null;
}

interface UpcomingTransactionsManagerProps {
  upcomingTransactions: Transaction[];
  overdueTransactions: Transaction[];
}

export function UpcomingTransactionsManager({
  upcomingTransactions,
  overdueTransactions,
}: UpcomingTransactionsManagerProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatDay = (dateStr: string) => {
    return format(parseISO(dateStr), "dd/MM", { locale: ptBR });
  };

  const formatFullDate = (dateStr: string) => {
    return format(parseISO(dateStr), "dd/MM/yyyy", { locale: ptBR });
  };

  // Calculate overdue totals
  const overdueExpenses = overdueTransactions.filter(
    (tx) => tx.type === 'expense' || tx.type === 'credit_card_expense'
  );
  const overdueIncomes = overdueTransactions.filter((tx) => tx.type === 'income');

  const totalOverdueExpenses = overdueExpenses.reduce((sum, tx) => sum + Number(tx.amount), 0);
  const totalOverdueIncomes = overdueIncomes.reduce((sum, tx) => sum + Number(tx.amount), 0);
  const netOverdueAmount = totalOverdueIncomes - totalOverdueExpenses;

  const hasOverdue = overdueTransactions.length > 0;

  return (
    <>
      <Card className="flex flex-col h-[600px]">
        <CardHeader>
          <CardTitle className="text-lg font-medium flex items-center gap-2">
            <WalletCards className="w-5 h-5 text-muted-foreground" />
            Próximos Lançamentos (Gerenciador)
          </CardTitle>
        </CardHeader>
        <CardContent className="flex-1 overflow-y-auto p-0">
          {upcomingTransactions.length === 0 && !hasOverdue ? (
            <div className="text-center p-12 text-muted-foreground border-t border-dashed">
              Nenhum lançamento previsto ou em atraso.
            </div>
          ) : (
            <div className="overflow-x-auto">
            <Table>
              <TableHeader className="sticky top-0 bg-background z-10">
                <TableRow>
                  <TableHead className="px-2 md:px-4 text-xs md:text-sm">Data</TableHead>
                  <TableHead className="px-2 md:px-4 text-xs md:text-sm">Descrição</TableHead>
                  <TableHead className="text-right px-2 md:px-4 text-xs md:text-sm">Valor</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {/* Overdue Group Row (displays first if exists) */}
                {hasOverdue && (
                  <TableRow
                    onClick={() => setIsDialogOpen(true)}
                    className="cursor-pointer bg-red-500/5 hover:bg-red-500/10 dark:bg-red-900/10 dark:hover:bg-red-900/20 transition-colors group"
                  >
                    <TableCell className="py-3 md:py-5 px-2 md:px-4">
                      <div className="bg-red-500/10 text-red-500 px-2 md:px-3 py-1 md:py-1.5 rounded-full inline-flex items-center gap-1 md:gap-1.5 font-bold text-[10px] md:text-xs">
                        <AlertTriangle className="w-3 h-3 md:w-3.5 md:h-3.5 shrink-0" />
                        <span className="hidden sm:inline">Vencidas</span>
                        <span className="sm:hidden">Atraso</span>
                      </div>
                    </TableCell>
                    <TableCell className="py-3 md:py-5 px-2 md:px-4 min-w-0">
                      <div className="flex flex-col min-w-0">
                        <span className="font-semibold text-red-500 dark:text-red-400 text-xs md:text-sm truncate max-w-[120px] sm:max-w-none">
                          {overdueTransactions.length} {overdueTransactions.length === 1 ? 'atrasado' : 'atrasados'}
                        </span>
                        <span className="text-[10px] md:text-xs text-muted-foreground truncate max-w-[120px] sm:max-w-[200px] md:max-w-none">
                          {overdueTransactions.map((tx) => tx.description).join(', ')}
                        </span>
                      </div>
                    </TableCell>
                    <TableCell className={`text-right font-bold whitespace-nowrap py-3 md:py-4 px-2 md:px-4 text-xs md:text-sm ${netOverdueAmount >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-500'}`}>
                      {netOverdueAmount >= 0 ? '+' : '-'}{formatCurrency(Math.abs(netOverdueAmount))}
                    </TableCell>
                  </TableRow>
                )}

                {/* Upcoming/Future Rows */}
                {upcomingTransactions.map((tx) => {
                  const isIncome = tx.type === 'income' || (tx.type === 'transfer' && !!tx.parentTransactionId);
                  const isTransfer = tx.type === 'transfer';
                  return (
                    <TableRow key={tx.id} className="hover:bg-muted/30">
                      <TableCell className="font-medium whitespace-nowrap py-3 md:py-4 px-2 md:px-4 text-xs md:text-sm">
                        {formatDay(tx.date)}
                      </TableCell>
                      <TableCell className="py-3 md:py-4 px-2 md:px-4 min-w-0">
                        <div className="flex flex-col min-w-0">
                          <span className="font-medium truncate max-w-[120px] sm:max-w-none text-xs md:text-sm" title={tx.description}>
                            {isTransfer && <span className="inline-block bg-blue-100 text-blue-700 border border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800 text-[9px] uppercase px-1 rounded mr-1">Transf</span>}
                            {tx.description}
                          </span>
                          <span className="text-[10px] md:text-xs text-muted-foreground truncate max-w-[120px] sm:max-w-none">
                            {tx.account?.name || tx.creditCard?.name || 'Geral'} • {tx.category?.name}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className={`text-right font-bold whitespace-nowrap py-3 md:py-4 px-2 md:px-4 text-xs md:text-sm ${isIncome ? 'text-green-600' : 'text-red-500'}`}>
                        {isIncome ? '+' : '-'}{formatCurrency(Number(tx.amount))}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Overdue Transactions Detail Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-[550px]">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-red-500">
              <AlertTriangle className="w-5 h-5" />
              Lançamentos Vencidos
            </DialogTitle>
            <DialogDescription>
              Estes lançamentos estão com status pendente e a data de vencimento já passou.
            </DialogDescription>
          </DialogHeader>

          {/* Quick Summary */}
          <div className="grid grid-cols-2 gap-3 my-2">
            <div className="rounded-lg border p-3 text-center bg-red-500/5 dark:bg-red-950/10">
              <span className="text-xs text-muted-foreground block mb-1">Total Despesas</span>
              <span className="font-bold text-red-500 text-sm">
                {formatCurrency(totalOverdueExpenses)}
              </span>
            </div>
            <div className="rounded-lg border p-3 text-center bg-green-500/5 dark:bg-green-950/10">
              <span className="text-xs text-muted-foreground block mb-1">Total Receitas</span>
              <span className="font-bold text-green-600 dark:text-green-400 text-sm">
                {formatCurrency(totalOverdueIncomes)}
              </span>
            </div>
          </div>

          <div className="max-h-[350px] overflow-y-auto overflow-x-auto border rounded-lg">
            <Table>
              <TableHeader className="bg-muted/50 sticky top-0">
                <TableRow>
                  <TableHead>Vencimento</TableHead>
                  <TableHead>Descrição</TableHead>
                  <TableHead className="text-right">Valor</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {overdueTransactions.map((tx) => {
                  const isIncome = tx.type === 'income' || (tx.type === 'transfer' && !!tx.parentTransactionId);
                  const isTransfer = tx.type === 'transfer';
                  return (
                    <TableRow key={tx.id} className="hover:bg-muted/40">
                      <TableCell className="font-medium whitespace-nowrap text-xs text-red-500">
                        {formatFullDate(tx.date)}
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          <span className="font-medium text-sm line-clamp-1">
                            {isTransfer && <span className="inline-block bg-blue-100 text-blue-700 border border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800 text-[9px] uppercase px-1 rounded mr-1">Transf</span>}
                            {tx.description}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            {tx.account?.name || tx.creditCard?.name || 'Geral'} • {tx.category?.name}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className={`text-right font-bold whitespace-nowrap text-sm ${isIncome ? 'text-green-600 dark:text-green-400' : 'text-red-500'}`}>
                        {isIncome ? '+' : '-'}{formatCurrency(Number(tx.amount))}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

