'use client';

import { useState } from 'react';
import { updateClosingDay } from '@/app/actions/settings';
import { fixAllCompetencies, backfillInvoiceMonths } from '@/app/actions/transactions';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';

export function SettingsForm({ initialClosingDay }: { initialClosingDay: number }) {
  const [isPending, setIsPending] = useState(false);
  const [isFixing, setIsFixing] = useState(false);
  const [isBackfilling, setIsBackfilling] = useState(false);
  const [message, setMessage] = useState('');

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsPending(true);
    setMessage('');

    const formData = new FormData(e.currentTarget);
    const closingDay = Number(formData.get('closingDay'));

    const result = await updateClosingDay(closingDay);

    if (result.success) {
      setMessage('Configurações salvas com sucesso!');
      toast.success('Configurações salvas com sucesso!');
    } else {
      setMessage('Erro ao salvar as configurações.');
      toast.error('Erro ao salvar as configurações.');
    }

    setIsPending(false);
  };

  const handleFixFaturas = async () => {
    setIsFixing(true);
    try {
      const res = await fixAllCompetencies();
      if (res.success) {
        toast.success(`${res.count} faturas antigas foram corrigidas.`);
      }
    } catch (e) {
      toast.error("Erro ao corrigir faturas.");
    }
    setIsFixing(false);
  };

  const handleBackfillInvoice = async () => {
    setIsBackfilling(true);
    try {
      const res = await backfillInvoiceMonths();
      if (res.success) {
        toast.success(`${res.count} transações antigas de cartão foram preenchidas com invoice_month.`);
      }
    } catch (e) {
      toast.error("Erro ao preencher meses de fatura.");
    }
    setIsBackfilling(false);
  };

  return (
    <div className="space-y-6">
      <Card className="w-full max-w-md mt-8">
        <CardHeader>
          <CardTitle>Configurações</CardTitle>
          <CardDescription>Gerencie suas preferências do sistema.</CardDescription>
        </CardHeader>
        <form onSubmit={handleSubmit}>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="closingDay">Dia de Fechamento do Mês</Label>
              <Input 
                id="closingDay" 
                name="closingDay" 
                type="number" 
                min="1" 
                max="31" 
                defaultValue={initialClosingDay}
                required 
              />
              <p className="text-sm text-muted-foreground">
                Usado para calcular os totais mensais baseados em quando o seu mês contábil &quot;vira&quot;.
              </p>
            </div>
            {message && (
              <p className={`text-sm font-medium ${message.includes('Erro') ? 'text-destructive' : 'text-green-600 dark:text-green-400'}`}>
                {message}
              </p>
            )}
          </CardContent>
          <CardFooter>
            <Button type="submit" isLoading={isPending} disabled={isPending}>

              {isPending ? 'Salvando...' : 'Salvar Alterações'}
            </Button>
          </CardFooter>
        </form>
      </Card>

      {/* Botão Temporário para correção de banco de dados */}
      <Card className="w-full max-w-md border-orange-500/20 bg-orange-500/5">
        <CardHeader>
          <CardTitle className="text-orange-600">Correções Manuais (Temporário)</CardTitle>
          <CardDescription>Ações de administração de dados.</CardDescription>
        </CardHeader>
        <CardContent>
          <Button 
            variant="outline" 
            onClick={handleFixFaturas} 
            disabled={isFixing}
            className="w-full border-orange-500/50 text-orange-600 hover:bg-orange-500/10 hover:text-orange-700"
          >

            Corrigir Todas as Competências
          </Button>
          <Button 
            variant="outline" 
            onClick={handleBackfillInvoice} 
            disabled={isBackfilling}
            className="w-full border-orange-500/50 text-orange-600 hover:bg-orange-500/10 hover:text-orange-700 mt-2"
          >

            Restaurar Faturas Antigas
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

'use server';

import { db } from '@/db';
import { creditCards, transactions, accounts, categories, subcategories } from '@/db/schema';
import { eq, and, ne, or, isNull } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';
import { format } from 'date-fns';
import { auth } from '@/auth';
import { getTargetInvoiceMonth, buildCreditCardCompetencyCondition } from '@/lib/competency-utils';
import { settings } from '@/db/schema';

export async function getCreditCards() {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  return await db.select().from(creditCards).where(eq(creditCards.userId, session.user.id));
}

export async function createCreditCard(data: Omit<typeof creditCards.$inferInsert, 'userId'>) {
  try {
    const session = await auth();
    if (!session?.user?.id) throw new Error("Unauthorized");
    await db.insert(creditCards).values({ ...data, userId: session.user.id });
    revalidatePath('/credit-cards');
    return { success: true };
  } catch (error) {
    console.error('Error creating credit card:', error);
    return { success: false, error: 'Failed to create credit card' };
  }
}

export async function getCreditCard(id: number) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const [card] = await db.select().from(creditCards).where(and(eq(creditCards.id, id), eq(creditCards.userId, session.user.id)));
  return card;
}

export async function updateCreditCard(id: number, data: Partial<typeof creditCards.$inferInsert>) {
  try {
    const session = await auth();
    if (!session?.user?.id) throw new Error("Unauthorized");
    await db.update(creditCards).set(data).where(and(eq(creditCards.id, id), eq(creditCards.userId, session.user.id)));
    revalidatePath('/credit-cards');
    revalidatePath(`/credit-cards/${id}`);
    return { success: true };
  } catch (error) {
    console.error('Error updating credit card:', error);
    return { success: false, error: 'Failed to update credit card' };
  }
}

export async function deleteCreditCard(id: number) {
  try {
    const session = await auth();
    if (!session?.user?.id) throw new Error("Unauthorized");
    const userId = session.user.id;

    const linkedTxs = await db.select({ id: transactions.id })
      .from(transactions)
      .where(and(eq(transactions.creditCardId, id), eq(transactions.userId, userId)))
      .limit(1);

    if (linkedTxs.length > 0) {
      return { success: false, error: 'Não é possível excluir: existem transações vinculadas a este cartão.' };
    }

    await db.delete(creditCards).where(and(eq(creditCards.id, id), eq(creditCards.userId, userId)));
    revalidatePath('/credit-cards');
    revalidatePath('/dashboard');
    return { success: true };
  } catch (error) {
    console.error('Error deleting credit card:', error);
    return { success: false, error: 'Falha ao excluir cartão de crédito' };
  }
}

export async function getInvoiceSummary(creditCardId: string | number, competencyMonth: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;
  const parsedId = Number(creditCardId);
  const cardTransactions = await db.query.transactions.findMany({
    where: (t, { eq, ne, and, or, isNull }) => and(
      eq(t.creditCardId, parsedId),
      or(
        eq(t.invoiceMonth, competencyMonth),
        and(isNull(t.invoiceMonth), eq(t.competencyMonth, competencyMonth))
      ),
      eq(t.type, 'credit_card_expense'),
      ne(t.status, 'ignored'),
      eq(t.userId, userId)
    ),
    with: {
      category: true,
      subcategory: true,
    },
    orderBy: (t, { desc }) => [desc(t.date)],
  });

  let total_amount = 0;
  let pending_amount = 0;

  for (const t of cardTransactions) {
    const amount = Number(t.amount);
    if (amount > 0) {
      total_amount += amount;
    }
    if (t.status === 'pending') {
      pending_amount += amount;
    }
  }

  const paid_amount = total_amount - pending_amount;
  const summary = { total_amount, paid_amount, pending_amount };

  return {
    ...summary,
    transactions: cardTransactions,
  };
}

export async function payFullInvoice(
  creditCardId: string | number,
  competencyMonth: string,
  accountId: string | number
): Promise<{ success: boolean; error?: string }> {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;
  const parsedCardId = Number(creditCardId);
  const parsedAccountId = Number(accountId);

  try {
    const result = await db.transaction(async (tx) => {
      // 1. Get pending amount
      const cardTransactions = await tx.select()
        .from(transactions)
        .where(
          and(
            eq(transactions.creditCardId, parsedCardId),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            eq(transactions.userId, userId)
          )
        );

      let pendingAmount = 0;
      for (const t of cardTransactions) {
        if (t.status === 'pending') {
          pendingAmount += Number(t.amount);
        }
      }

      if (pendingAmount <= 0) {
        throw new Error('Não há valor pendente para pagar nesta fatura');
      }

      // 2. Update transactions to 'paid'
      await tx.update(transactions)
        .set({ status: 'paid' })
        .where(
          and(
            eq(transactions.creditCardId, parsedCardId),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            eq(transactions.status, 'pending'),
            eq(transactions.userId, userId)
          )
        );

      // 3. Find or create Category for "Pagamento de Fatura"
      let category = await tx.query.categories.findFirst({
        where: (categories, { eq, and }) => and(eq(categories.name, 'Pagamento de Fatura'), eq(categories.userId, userId))
      });
      let subcategoryId = null;

      if (!category) {
        const [newCategory] = await tx.insert(categories)
          .values({ userId, name: 'Pagamento de Fatura', type: 'expense', icon: 'CreditCard' })
          .returning();

        const [newSubcategory] = await tx.insert(subcategories)
          .values({ userId, name: 'Geral', categoryId: newCategory.id })
          .returning();

        category = newCategory;
        subcategoryId = newSubcategory.id;
      } else {
        const subcategory = await tx.query.subcategories.findFirst({
          where: (subcategories, { eq, and }) => and(eq(subcategories.categoryId, category!.id), eq(subcategories.userId, userId))
        });
        subcategoryId = subcategory?.id || null;

        if (!subcategoryId) {
          const [newSubcategory] = await tx.insert(subcategories)
            .values({ userId, name: 'Geral', categoryId: category.id })
            .returning();
          subcategoryId = newSubcategory.id;
        }
      }

      // 4. Create the transfer transaction for the payment (avoids double counting in expenses)
      await tx.insert(transactions).values({
        userId,
        type: 'transfer',
        accountId: parsedAccountId,
        creditCardId: parsedCardId,
        categoryId: category.id,
        subcategoryId: subcategoryId,
        amount: pendingAmount.toString(),
        description: `Pagamento de Fatura - ${competencyMonth}`,
        date: format(new Date(), 'yyyy-MM-dd'),
        competencyMonth: competencyMonth,
        status: 'paid',
      });

      // 5. Deduct from account balance
      const [account] = await tx.select().from(accounts).where(and(eq(accounts.id, parsedAccountId), eq(accounts.userId, userId)));
      if (account) {
        const newBalance = Number(account.currentBalance) - pendingAmount;
        await tx.update(accounts)
          .set({ currentBalance: newBalance.toString() })
          .where(and(eq(accounts.id, parsedAccountId), eq(accounts.userId, userId)));
      }

      return { success: true };
    });

    revalidatePath('/credit-cards');
    revalidatePath(`/credit-cards/${parsedCardId}`);
    revalidatePath('/dashboard');
    revalidatePath('/transactions');
    return result;
  } catch (error) {
    console.error('Error paying full invoice:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Falha ao pagar fatura' };
  }
}

export async function prepayInvoice(
  creditCardId: string | number,
  competencyMonth: string,
  accountId: string | number,
  amount: number,
  date: string
): Promise<{ success: boolean; error?: string }> {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;
  const parsedCardId = Number(creditCardId);
  const parsedAccountId = Number(accountId);

  try {
    const result = await db.transaction(async (tx) => {
      // 1. Get pending amount to ensure they don't prepay more than owed
      const cardTransactions = await tx.select()
        .from(transactions)
        .where(
          and(
            eq(transactions.creditCardId, parsedCardId),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            eq(transactions.userId, userId)
          )
        );

      let pendingAmount = 0;
      for (const t of cardTransactions) {
        if (t.status === 'pending') {
          pendingAmount += Number(t.amount);
        }
      }

      if (pendingAmount <= 0) {
        throw new Error('Não há valor pendente para adiantar nesta fatura');
      }

      if (amount > pendingAmount) {
        throw new Error('O valor do adiantamento não pode ser maior que o saldo devedor pendente da fatura');
      }

      // 2. Find or create Category for "Pagamento de Fatura"
      let category = await tx.query.categories.findFirst({
        where: (categories, { eq, and }) => and(eq(categories.name, 'Pagamento de Fatura'), eq(categories.userId, userId))
      });
      let subcategoryId = null;

      if (!category) {
        const [newCategory] = await tx.insert(categories)
          .values({ userId, name: 'Pagamento de Fatura', type: 'expense', icon: 'CreditCard' })
          .returning();

        const [newSubcategory] = await tx.insert(subcategories)
          .values({ userId, name: 'Geral', categoryId: newCategory.id })
          .returning();

        category = newCategory;
        subcategoryId = newSubcategory.id;
      } else {
        const subcategory = await tx.query.subcategories.findFirst({
          where: (subcategories, { eq, and }) => and(eq(subcategories.categoryId, category!.id), eq(subcategories.userId, userId))
        });
        subcategoryId = subcategory?.id || null;

        if (!subcategoryId) {
          const [newSubcategory] = await tx.insert(subcategories)
            .values({ userId, name: 'Geral', categoryId: category.id })
            .returning();
          subcategoryId = newSubcategory.id;
        }
      }

      // 3. Create the transfer transaction (money leaving the checking account)
      await tx.insert(transactions).values({
        userId,
        type: 'transfer',
        accountId: parsedAccountId,
        creditCardId: parsedCardId,
        categoryId: category.id,
        subcategoryId: subcategoryId,
        amount: amount.toString(),
        description: `Adiantamento de Fatura - ${competencyMonth}`,
        date: date,
        competencyMonth: competencyMonth,
        status: 'paid',
      });

      // 4. Create the negative expense on the credit card (reducing pending amount)
      await tx.insert(transactions).values({
        userId,
        type: 'credit_card_expense',
        creditCardId: parsedCardId,
        categoryId: category.id,
        subcategoryId: subcategoryId,
        amount: (-amount).toString(), // Negative amount
        description: `Adiantamento de Fatura`,
        date: date,
        competencyMonth: competencyMonth,
        invoiceMonth: competencyMonth,
        status: 'pending', // Keeps it pending so it reduces the pending sum, and gets marked as paid later
      });

      // 5. Deduct from checking account balance
      const [account] = await tx.select().from(accounts).where(and(eq(accounts.id, parsedAccountId), eq(accounts.userId, userId)));
      if (account) {
        const newBalance = Number(account.currentBalance) - amount;
        await tx.update(accounts)
          .set({ currentBalance: newBalance.toString() })
          .where(and(eq(accounts.id, parsedAccountId), eq(accounts.userId, userId)));
      }

      return { success: true };
    });

    revalidatePath('/credit-cards');
    revalidatePath(`/credit-cards/${parsedCardId}`);
    revalidatePath('/dashboard');
    revalidatePath('/transactions');
    revalidatePath('/planning');
    return result;
  } catch (error) {
    console.error('Error prepaying invoice:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Falha ao adiantar fatura' };
  }
}

export async function getCreditCardsWithSummary(competencyMonth: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;

  const [appSettings] = await db.select().from(settings).where(eq(settings.userId, userId)).limit(1);
  const closingDay = appSettings?.closingDay || 25;

  const cards = await db.select().from(creditCards).where(eq(creditCards.userId, userId));

  const cardsWithSummary = await Promise.all(
    cards.map(async (card) => {
      // Busca transações do cartão na competência informada (Invoice Month)
      const cardTxs = await db.select()
        .from(transactions)
        .where(
          and(
            eq(transactions.creditCardId, card.id),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            ne(transactions.status, 'ignored'),
            eq(transactions.userId, userId)
          )
        );

      let invoice_total = 0;
      let invoice_pending = 0;

      for (const t of cardTxs) {
        const amount = Number(t.amount);
        if (amount > 0) {
          invoice_total += amount;
        }
        if (t.status === 'pending') {
          invoice_pending += amount;
        }
      }

      const invoice_paid = invoice_total - invoice_pending;

      return {
        ...card,
        invoice_total,
        invoice_paid,
        invoice_pending,
        targetInvoiceMonth: competencyMonth,
      };
    })
  );

  return cardsWithSummary;
}

export async function adjustInvoice(
  creditCardId: string | number,
  competencyMonth: string,
  realAmount: number
): Promise<{ success: boolean; error?: string; adjustmentType?: 'increase' | 'decrease' | 'none'; difference?: number }> {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;
  const parsedCardId = Number(creditCardId);

  try {
    const result = await db.transaction(async (tx) => {
      // 1. Calculate current invoice total (same logic as getInvoiceSummary)
      const cardTransactions = await tx.select()
        .from(transactions)
        .where(
          and(
            eq(transactions.creditCardId, parsedCardId),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            ne(transactions.status, 'ignored'),
            eq(transactions.userId, userId)
          )
        );

      let currentTotal = 0;
      for (const t of cardTransactions) {
        const amount = Number(t.amount);
        if (amount > 0) {
          currentTotal += amount;
        }
      }

      const diff = realAmount - currentTotal;

      if (Math.abs(diff) < 0.01) {
        return { success: true, adjustmentType: 'none' as const, difference: 0 };
      }

      // 2. Find or create appropriate category
      if (diff > 0) {
        // Real > Calculated: missing expense, create adjustment
        let category = await tx.query.categories.findFirst({
          where: (categories, { eq, and }) => and(eq(categories.name, 'Ajuste de Fatura'), eq(categories.userId, userId))
        });
        let subcategoryId = null;

        if (!category) {
          const [newCategory] = await tx.insert(categories)
            .values({ userId, name: 'Ajuste de Fatura', type: 'expense', icon: 'Settings' })
            .returning();

          const [newSubcategory] = await tx.insert(subcategories)
            .values({ userId, name: 'Geral', categoryId: newCategory.id })
            .returning();

          category = newCategory;
          subcategoryId = newSubcategory.id;
        } else {
          const subcategory = await tx.query.subcategories.findFirst({
            where: (subcategories, { eq, and }) => and(eq(subcategories.categoryId, category!.id), eq(subcategories.userId, userId))
          });
          subcategoryId = subcategory?.id || null;

          if (!subcategoryId) {
            const [newSubcategory] = await tx.insert(subcategories)
              .values({ userId, name: 'Geral', categoryId: category.id })
              .returning();
            subcategoryId = newSubcategory.id;
          }
        }

        await tx.insert(transactions).values({
          userId,
          type: 'credit_card_expense',
          creditCardId: parsedCardId,
          categoryId: category.id,
          subcategoryId: subcategoryId,
          amount: diff.toFixed(2),
          description: `Ajuste de Fatura - ${competencyMonth}`,
          date: format(new Date(), 'yyyy-MM-dd'),
          competencyMonth: competencyMonth,
          invoiceMonth: competencyMonth,
          status: 'pending',
        });

        return { success: true, adjustmentType: 'increase' as const, difference: diff };
      } else {
        // Real < Calculated: overstated, create negative credit
        let category = await tx.query.categories.findFirst({
          where: (categories, { eq, and }) => and(eq(categories.name, 'Pagamento de Fatura'), eq(categories.userId, userId))
        });
        let subcategoryId = null;

        if (!category) {
          const [newCategory] = await tx.insert(categories)
            .values({ userId, name: 'Pagamento de Fatura', type: 'expense', icon: 'CreditCard' })
            .returning();

          const [newSubcategory] = await tx.insert(subcategories)
            .values({ userId, name: 'Geral', categoryId: newCategory.id })
            .returning();

          category = newCategory;
          subcategoryId = newSubcategory.id;
        } else {
          const subcategory = await tx.query.subcategories.findFirst({
            where: (subcategories, { eq, and }) => and(eq(subcategories.categoryId, category!.id), eq(subcategories.userId, userId))
          });
          subcategoryId = subcategory?.id || null;

          if (!subcategoryId) {
            const [newSubcategory] = await tx.insert(subcategories)
              .values({ userId, name: 'Geral', categoryId: category.id })
              .returning();
            subcategoryId = newSubcategory.id;
          }
        }

        await tx.insert(transactions).values({
          userId,
          type: 'credit_card_expense',
          creditCardId: parsedCardId,
          categoryId: category.id,
          subcategoryId: subcategoryId,
          amount: diff.toFixed(2), // negative value
          description: `Adiantamento de Fatura - ${competencyMonth}`,
          date: format(new Date(), 'yyyy-MM-dd'),
          competencyMonth: competencyMonth,
          invoiceMonth: competencyMonth,
          status: 'pending',
        });

        return { success: true, adjustmentType: 'decrease' as const, difference: diff };
      }
    });

    revalidatePath('/credit-cards');
    revalidatePath(`/credit-cards/${parsedCardId}`);
    revalidatePath('/dashboard');
    revalidatePath('/transactions');
    revalidatePath('/planning');
    return result;
  } catch (error) {
    console.error('Error adjusting invoice:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Falha ao ajustar fatura' };
  }
}

export async function getCreditCardsCategorySummary(competencyMonth: string) {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;

  const [appSettings] = await db.select().from(settings).where(eq(settings.userId, userId)).limit(1);
  const closingDay = appSettings?.closingDay || 25;

  const userCards = await db.select({ id: creditCards.id, dueDay: creditCards.dueDay }).from(creditCards).where(eq(creditCards.userId, userId));
  const condition = buildCreditCardCompetencyCondition(competencyMonth, closingDay, userId, userCards);

  const cardTxs = await db.query.transactions.findMany({
    where: and(condition, ne(transactions.status, 'ignored')),
    with: {
      category: true,
      subcategory: true,
    }
  });

  const categoryMap = new Map<string, { value: number; subcategories: Map<string, number> }>();

  for (const t of cardTxs) {
    const amount = Number(t.amount);
    const categoryName = t.category?.name || 'Sem Categoria';
    const subcategoryName = t.subcategory?.name || 'Geral';

    if (!categoryMap.has(categoryName)) {
      categoryMap.set(categoryName, { value: 0, subcategories: new Map() });
    }

    const catData = categoryMap.get(categoryName)!;
    catData.value += amount;
    catData.subcategories.set(subcategoryName, (catData.subcategories.get(subcategoryName) || 0) + amount);
  }

  const result = Array.from(categoryMap.entries()).map(([category, data]) => ({
    category,
    value: data.value,
    subcategories: Array.from(data.subcategories.entries())
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value)
  }));

  // Sort descending by value
  result.sort((a, b) => b.value - a.value);

  return result;
}

export async function revertInvoicePayment(
  creditCardId: string | number,
  competencyMonth: string
): Promise<{ success: boolean; error?: string }> {
  const session = await auth();
  if (!session?.user?.id) throw new Error("Unauthorized");
  const userId = session.user.id;
  const parsedCardId = Number(creditCardId);

  try {
    const result = await db.transaction(async (tx) => {
      // 1. Mark expenses as pending
      await tx.update(transactions)
        .set({ status: 'pending' })
        .where(
          and(
            eq(transactions.creditCardId, parsedCardId),
            or(
              eq(transactions.invoiceMonth, competencyMonth),
              and(isNull(transactions.invoiceMonth), eq(transactions.competencyMonth, competencyMonth))
            ),
            eq(transactions.type, 'credit_card_expense'),
            eq(transactions.status, 'paid'),
            eq(transactions.userId, userId)
          )
        );

      // 2. Find transfer transactions related to this invoice payment
      const paymentTransfers = await tx.select().from(transactions).where(
        and(
          eq(transactions.userId, userId),
          eq(transactions.type, 'transfer'),
          eq(transactions.competencyMonth, competencyMonth),
          or(
            eq(transactions.creditCardId, parsedCardId),
            and(
              isNull(transactions.creditCardId),
              or(
                sql`${transactions.description} LIKE 'Pagamento de Fatura - %'`,
                sql`${transactions.description} LIKE 'Adiantamento de Fatura - %'`
              )
            )
          )
        )
      );

      // 3. Delete transfers and refund accounts
      for (const t of paymentTransfers) {
        if (t.accountId) {
          const [account] = await tx.select().from(accounts).where(and(eq(accounts.id, t.accountId), eq(accounts.userId, userId)));
          if (account) {
            const newBalance = Number(account.currentBalance) + Number(t.amount);
            await tx.update(accounts)
              .set({ currentBalance: newBalance.toString() })
              .where(and(eq(accounts.id, t.accountId), eq(accounts.userId, userId)));
          }
        }
        await tx.delete(transactions).where(eq(transactions.id, t.id));
      }

      // 4. Delete negative credit card expenses that were created for prepayment
      const prepaymentExpenses = await tx.select().from(transactions).where(
        and(
          eq(transactions.userId, userId),
          eq(transactions.type, 'credit_card_expense'),
          eq(transactions.creditCardId, parsedCardId),
          eq(transactions.competencyMonth, competencyMonth),
          sql`${transactions.amount} < 0`,
          sql`${transactions.description} = 'Adiantamento de Fatura'`
        )
      );
      for (const t of prepaymentExpenses) {
        await tx.delete(transactions).where(eq(transactions.id, t.id));
      }

      return { success: true };
    });

    revalidatePath('/credit-cards');
    revalidatePath(`/credit-cards/${parsedCardId}`);
    revalidatePath('/dashboard');
    revalidatePath('/transactions');
    return result;
  } catch (error) {
    console.error('Error reverting invoice payment:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Falha ao estornar fatura' };
  }
}

'use server';

import { db } from '@/db';
import { transactions, importLogs, settings, categories, subcategories, accounts, creditCards } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';
import Papa from 'papaparse';
import { parse, isValid, addMonths, format, getDate } from 'date-fns';
import crypto from 'crypto';
import { auth } from '@/auth';

function generateImportHash(description: string, amount: string, date: string, accountOrCardName: string, extra: string = ''): string {
  const hashStr = `${description.trim().toLowerCase()}|${amount}|${date}|${accountOrCardName.trim().toLowerCase()}${extra ? '|' + extra : ''}`;
  return crypto.createHash('sha256').update(hashStr).digest('hex');
}

function parseInstallments(description: string) {
  const match = description.match(/(.*?)\s+(\d{1,3})\/(\d{1,3})\s*$/);
  if (match) {
    return {
      cleanDescription: match[1].trim(),
      installmentCurrent: parseInt(match[2], 10),
      installmentTotal: parseInt(match[3], 10)
    };
  }
  return { cleanDescription: description.trim(), installmentCurrent: null, installmentTotal: null };
}

type ImportType = 'expense' | 'income' | 'transfer';

function getCompetencyMonth(date: Date, closingDay: number): string {
  const day = getDate(date);
  if (day > closingDay) {
    return format(addMonths(date, 1), 'yyyy-MM');
  }
  return format(date, 'yyyy-MM');
}

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  let parsed = parse(dateStr, 'yyyy-MM-dd', new Date());
  if (isValid(parsed)) return parsed;
  parsed = parse(dateStr, 'dd/MM/yyyy', new Date());
  if (isValid(parsed)) return parsed;
  return null;
}

function parseAmount(amountStr: string): string {
  if (!amountStr) return '0';
  let cleaned = amountStr.replace(/[R$\s]/g, '');
  if (cleaned.includes(',') && cleaned.includes('.')) {
    cleaned = cleaned.replace(/\./g, '').replace(',', '.');
  } else if (cleaned.includes(',')) {
    cleaned = cleaned.replace(',', '.');
  }
  const parsed = parseFloat(cleaned);
  return isNaN(parsed) ? '0' : Math.abs(parsed).toString();
}

type DbState = {
  accountsMap: Map<string, number>;
  cardsMap: Map<string, { id: number, closingDay: number, dueDay: number }>;
  categoriesMap: Map<string, number>;
  subcategoriesMap: Map<string, number>;
};

async function getOrCreateAccount(name: string, dbState: DbState, userId: string) {
  const lowerName = name.toLowerCase();
  if (dbState.accountsMap.has(lowerName)) {
    return dbState.accountsMap.get(lowerName)!;
  }
  const [newAcc] = await db.insert(accounts).values({
    userId,
    name: name,
    type: 'checking',
  }).returning();
  dbState.accountsMap.set(lowerName, newAcc.id);
  return newAcc.id;
}

async function getOrCreateCard(name: string, closingDay: number, dbState: DbState, userId: string) {
  const lowerName = name.toLowerCase();
  if (dbState.cardsMap.has(lowerName)) {
    return dbState.cardsMap.get(lowerName)!;
  }
  const [newCard] = await db.insert(creditCards).values({
    userId,
    name: name,
    creditLimit: '0',
    closingDay,
    dueDay: 10,
  }).returning();
  const cardData = { id: newCard.id, closingDay: newCard.closingDay, dueDay: newCard.dueDay };
  dbState.cardsMap.set(lowerName, cardData);
  return cardData;
}

async function getOrCreateCategory(catName: string, subName: string | undefined, transactionType: string, dbState: DbState, userId: string) {
  let categoryId = null;
  const lowerCat = catName.toLowerCase();

  if (dbState.categoriesMap.has(lowerCat)) {
    categoryId = dbState.categoriesMap.get(lowerCat)!;
  } else {
    const [newCat] = await db.insert(categories).values({
      userId,
      name: catName,
      type: transactionType === 'transfer' ? 'expense' : transactionType,
    }).returning();
    dbState.categoriesMap.set(lowerCat, newCat.id);
    categoryId = newCat.id;

    const [newSub] = await db.insert(subcategories).values({
      userId,
      name: 'Geral',
      categoryId: newCat.id,
    }).returning();
    dbState.subcategoriesMap.set(`${newCat.id}_geral`, newSub.id);
  }

  let subcategoryId = null;
  if (subName) {
    const lowerSub = subName.toLowerCase();
    const key = `${categoryId}_${lowerSub}`;
    if (dbState.subcategoriesMap.has(key)) {
      subcategoryId = dbState.subcategoriesMap.get(key)!;
    } else {
      const [newSub] = await db.insert(subcategories).values({
        userId,
        name: subName,
        categoryId,
      }).returning();
      dbState.subcategoriesMap.set(key, newSub.id);
      subcategoryId = newSub.id;
    }
  } else {
    const key = `${categoryId}_geral`;
    if (dbState.subcategoriesMap.has(key)) {
      subcategoryId = dbState.subcategoriesMap.get(key)!;
    }
  }

  return { categoryId, subcategoryId };
}

async function processExpenses(rows: Record<string, string>[], dbState: DbState, closingDay: number, filename: string, userId: string) {
  const transactionsToInsert: typeof transactions.$inferInsert[] = [];
  const errorsDetail: { row: number; data: Record<string, string>; error: string }[] = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowIndex = i + 2;
    try {
      const getCol = (possibleNames: string[]) => {
        const key = Object.keys(row).find(k => possibleNames.includes(k.toUpperCase().trim()));
        return key ? row[key]?.trim() : '';
      };

      const vencimentoStr = getCol(['VENCIMENTO', 'DATA']);
      const efetivacaoStr = getCol(['EFETIVAÇÃO', 'EFETIVACAO', 'PAGAMENTO']);
      const descricao = getCol(['DESCRIÇÃO', 'DESCRICAO', 'NOME', 'HISTÓRICO', 'HISTORICO']) || '';
      const { cleanDescription, installmentCurrent, installmentTotal } = parseInstallments(descricao);
      const valorStr = getCol(['VALOR', 'QUANTIA', 'SAÍDA']);
      let cartaoName = getCol(['CARTÃO', 'CARTAO']);
      if (cartaoName === '-') cartaoName = '';

      let contaName = getCol(['CONTA', 'BANCO']);
      if (contaName === '-') contaName = '';
      const categoriaName = getCol(['CATEGORIA']);
      const subcategoriaName = getCol(['SUBCATEGORIA']);

      const dataVencimento = parseDate(vencimentoStr);
      if (!dataVencimento) throw new Error(`Data de Vencimento inválida ou não encontrada.`);

      const dataEfetivacao = parseDate(efetivacaoStr);
      const status = dataEfetivacao ? 'paid' : 'pending';
      const paidAt = dataEfetivacao || null;
      const amount = parseAmount(valorStr);

      let accountId = null;
      let creditCardId = null;
      let competencyMonth = '';

      if (cartaoName) {
        const card = await getOrCreateCard(cartaoName, closingDay, dbState, userId);
        creditCardId = card.id;
        const { calculateCreditCardDueDate } = await import('@/lib/utils/competency');
        const dueDate = calculateCreditCardDueDate(dataVencimento, card.closingDay, card.dueDay);
        competencyMonth = getCompetencyMonth(dueDate, closingDay);
      } else {
        competencyMonth = getCompetencyMonth(dataVencimento, closingDay);
      }

      if (contaName) {
        accountId = await getOrCreateAccount(contaName, dbState, userId);
      }

      if (!creditCardId && !accountId) {
        throw new Error('Conta ou Cartão não informado.');
      }

      if (!categoriaName) throw new Error('Categoria não informada.');
      const { categoryId, subcategoryId } = await getOrCreateCategory(categoriaName, subcategoriaName, 'expense', dbState, userId);

      transactionsToInsert.push({
        userId,
        type: creditCardId ? 'credit_card_expense' : 'expense',
        accountId,
        creditCardId,
        categoryId,
        subcategoryId,
        amount,
        description: cleanDescription || 'Despesa Importada',
        installmentCurrent,
        installmentTotal,
        date: format(dataVencimento, 'yyyy-MM-dd'),
        competencyMonth,
        status,
        paidAt,
        observations: `Importado do arquivo ${filename} - Linha ${rowIndex}`,
        importHash: generateImportHash(descricao || 'Despesa Importada', amount, dataVencimento.toISOString(), cartaoName || contaName || ''),
      });
    } catch (err: unknown) {
      errorsDetail.push({ row: rowIndex, data: row, error: err instanceof Error ? err.message : String(err) });
    }
  }

  let skippedRows = 0;
  let successRows = 0;

  if (transactionsToInsert.length > 0) {
    await db.transaction(async (tx) => {
      const result = await tx.insert(transactions)
        .values(transactionsToInsert)
        .onConflictDoNothing({ target: transactions.importHash })
        .returning({ id: transactions.id });
      successRows = result.length;
      skippedRows = transactionsToInsert.length - result.length;
    });
  }
  return { successRows, skippedRows, errorsDetail };
}

async function processIncomes(rows: Record<string, string>[], dbState: DbState, closingDay: number, filename: string, userId: string) {
  const transactionsToInsert: typeof transactions.$inferInsert[] = [];
  const errorsDetail: { row: number; data: Record<string, string>; error: string }[] = [];

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const rowIndex = i + 2;
    try {
      const getCol = (possibleNames: string[]) => {
        const key = Object.keys(row).find(k => possibleNames.includes(k.toUpperCase().trim()));
        return key ? row[key]?.trim() : '';
      };

      const vencimentoStr = getCol(['VENCIMENTO', 'DATA']);
      const efetivacaoStr = getCol(['EFETIVAÇÃO', 'EFETIVACAO', 'PAGAMENTO']);
